-- ════════════════════════════════════════════════════════════════════════
-- 2027-04-22-faction-catalogue.generated.sql — THE TWO FACTIONS: WHO MAY JOIN, WHAT A SWAP COSTS, WHICH GROUND PAYS WHICH SIDE, WHAT STANDING BUYS.
-- Generated by tools/gen-factions.mjs from src/data/factions.js and the hunt rows' `standingFor` (src/data/hunts.js).
--   Any hand edit FAILS `node tools/gen-factions.mjs --check`.
-- STATUS: STAGED, NOT APPLIED (lane/c-faction-standing, backend-architect, 2026-11-14). The Coordinator applies (tools/apply-migration.mjs,
--   one file, never inside begin/commit). ORDER: before 2027-04-22-faction-standing.sql, which reads all four tables. No function body.
-- A row moves no value: the verbs and the settle read it under the hero's lock, on the server's clock. hr_factions is upserted (a hero's
-- membership points at it); the rule is one row; hr_faction_grounds and hr_faction_outfits are rewritten whole, so a second apply is
-- byte-identical. hr_faction_grounds holds OPEN grounds only (a staged one is served nowhere): today none, the Morrow Hills are not built.
-- RLS on, no policy, no client grant: only SECURITY DEFINER functions read them. ON THE EA SECURITY LIST.
-- REVERSIBLE: drop the four tables after the verbs and the settle splice that read them (2027-04-22-faction-standing.sql's reversal).
-- ════════════════════════════════════════════════════════════════════════
create table if not exists public.hr_factions (
  faction_id text primary key check (faction_id ~ '^[a-z0-9_]{1,32}$'),
  ord        int  not null
);
create table if not exists public.hr_faction_rule (
  id           boolean primary key default true check (id),
  join_monster text   not null check (join_monster ~ '^[a-z0-9_]{1,40}$'),
  swap_ms      bigint not null check (swap_ms > 0),
  cooldown_ms  bigint not null check (cooldown_ms >= 0),
  day_cap_ms   bigint not null check (day_cap_ms between 60000 and 86400000)
);
create table if not exists public.hr_faction_grounds (
  hunt_id text primary key check (hunt_id ~ '^[a-z0-9_]{1,64}$'),
  faction text not null references public.hr_factions (faction_id)
);
create table if not exists public.hr_faction_outfits (
  piece_id text   primary key check (piece_id ~ '^[a-z0-9_]{1,32}$'),
  faction  text   not null references public.hr_factions (faction_id),
  need_ms  bigint not null check (need_ms > 0),
  ord      int    not null
);
do $$
declare t text;
begin
  foreach t in array array['hr_factions', 'hr_faction_rule', 'hr_faction_grounds', 'hr_faction_outfits'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated, service_role', t);
  end loop;
end $$;
comment on table public.hr_factions is '2027-04-22-faction-catalogue.generated.sql: the two sides (src/data/grounds/shape.js STANDING_SIDES). Upserted, never re-inserted: hr_faction_members points here.';
comment on table public.hr_faction_rule is '2027-04-22-faction-catalogue.generated.sql: the join monster, the swap''s hunting time, the swap cooldown and the day''s ceiling (src/data/factions.js FACTION_RULES), in ms.';
comment on table public.hr_faction_grounds is '2027-04-22-faction-catalogue.generated.sql: each OPEN ground (and keyed hall) whose settled hunting time pays standing, and to which side (hunt rows'' standingFor).';
comment on table public.hr_faction_outfits is '2027-04-22-faction-catalogue.generated.sql: each piece standing buys, its side and the standing it takes (src/data/factions.js FACTION_OUTFITS), in ms.';

insert into public.hr_factions (faction_id, ord) values
  ('first_flame', 0),
  ('last_ember', 1)
on conflict (faction_id) do update set ord = excluded.ord;

insert into public.hr_faction_rule (id, join_monster, swap_ms, cooldown_ms, day_cap_ms) values
  (true, 'lord_krell', 36000000, 604800000, 86400000)
on conflict (id) do update set join_monster = excluded.join_monster, swap_ms = excluded.swap_ms, cooldown_ms = excluded.cooldown_ms,
  day_cap_ms = excluded.day_cap_ms;

delete from public.hr_faction_grounds;
-- (no open ground pays standing in the data: the Morrow Hills are not built)

delete from public.hr_faction_outfits;
insert into public.hr_faction_outfits (piece_id, faction, need_ms, ord) values
  ('flamebearer', 'first_flame', 90000000, 0),
  ('flamebearer_shield', 'first_flame', 360000000, 1),
  ('flamebearer_light', 'first_flame', 1080000000, 2),
  ('emberkeeper', 'last_ember', 90000000, 3),
  ('emberkeeper_lantern', 'last_ember', 360000000, 4),
  ('emberkeeper_coal', 'last_ember', 1080000000, 5);

-- A side dropped from the data goes last, once nothing of the catalogue names it (a hero's membership still naming it refuses, loudly).
delete from public.hr_factions where faction_id <> all (array['first_flame', 'last_ember']::text[]);

-- §4 SELF-CHECK: the two sides, one rule, a piece for each side, every paying ground a hunt the server knows, and no client can read or
-- write a table.
do $$
declare t text; v_role text;
begin
  if (select count(*) from public.hr_factions) <> 2 then raise exception 'faction-catalogue §4: hr_factions does not hold the 2 sides'; end if;
  if not exists (select 1 from public.hr_faction_rule where id) then raise exception 'faction-catalogue §4: no rule row'; end if;
  if exists (select 1 from public.hr_factions f where not exists (select 1 from public.hr_faction_outfits o where o.faction = f.faction_id)) then
    raise exception 'faction-catalogue §4: a side has no piece to claim'; end if;
  if exists (select 1 from public.hr_faction_grounds g where not exists (select 1 from public.hr_hunts h where h.hunt_id = g.hunt_id)) then
    raise exception 'faction-catalogue §4: a paying ground is no hunt the server serves'; end if;
  foreach t in array array['hr_factions', 'hr_faction_rule', 'hr_faction_grounds', 'hr_faction_outfits'] loop
    if exists (select 1 from pg_policies where schemaname = 'public' and tablename = t) then
      raise exception 'faction-catalogue §4: a policy opens % to a client', t; end if;
    foreach v_role in array array['anon', 'authenticated'] loop
      if has_table_privilege(v_role, 'public.' || t, 'select') or has_table_privilege(v_role, 'public.' || t, 'insert,update,delete') then
        raise exception 'faction-catalogue §4: % holds a grant on %', v_role, t; end if;
    end loop;
  end loop;
end $$;
